inline ::flatbuffers::Offset<QRP> CreateQRP(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    qrpKind KIND = qrpKind_Request,
    qrpStatus STATUS = qrpStatus_Ok,
    ::flatbuffers::Offset<::flatbuffers::String> ERROR_CODE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> MESSAGE = 0,
    uint32_t RETRY_AFTER_MS = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SCHEMA_NAME = 0,
    ::flatbuffers::Offset<::flatbuffers::String> FILE_IDENTIFIER = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SQL = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SEARCH = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<QRPFilter>>> FILTERS = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SORT_FIELD = 0,
    bool SORT_DESC = false,
    ::flatbuffers::Offset<::flatbuffers::String> PROVIDER_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SOURCE_NAME = 0,
    ::flatbuffers::Offset<::flatbuffers::String> BATCH_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PRODUCER_PEER_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ORIGIN_ID = 0,
    int64_t FROM_EPOCH_MS = 0,
    int64_t TO_EPOCH_MS = 0,
    uint32_t PAGE = 0,
    uint32_t LIMIT = 0,
    ::flatbuffers::Offset<::flatbuffers::String> CURSOR = 0,
    ::flatbuffers::Offset<::flatbuffers::String> NEXT_CURSOR = 0,
    uint32_t RECORD_COUNT = 0,
    uint64_t TOTAL_COUNT = 0,
    uint64_t SCANNED = 0,
    uint64_t STORED = 0,
    bool PARTIAL = false,
    bool TRUNCATED = false,
    int64_t AS_OF_MS = 0,
    bool STALE = false,
    uint32_t ELAPSED_MS = 0,
    int64_t GENERATED_AT_MS = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ETAG = 0,
    ::flatbuffers::Offset<::flatbuffers::String> CID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ARCHIVE_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<QRPColumn>>> COLUMNS = 0) {
  QRPBuilder builder_(_fbb);
  builder_.add_GENERATED_AT_MS(GENERATED_AT_MS);
  builder_.add_AS_OF_MS(AS_OF_MS);
  builder_.add_STORED(STORED);
  builder_.add_SCANNED(SCANNED);
  builder_.add_TOTAL_COUNT(TOTAL_COUNT);
  builder_.add_TO_EPOCH_MS(TO_EPOCH_MS);
  builder_.add_FROM_EPOCH_MS(FROM_EPOCH_MS);
  builder_.add_COLUMNS(COLUMNS);
  builder_.add_ARCHIVE_ID(ARCHIVE_ID);
  builder_.add_CID(CID);
  builder_.add_ETAG(ETAG);
  builder_.add_ELAPSED_MS(ELAPSED_MS);
  builder_.add_RECORD_COUNT(RECORD_COUNT);
  builder_.add_NEXT_CURSOR(NEXT_CURSOR);
  builder_.add_CURSOR(CURSOR);
  builder_.add_LIMIT(LIMIT);
  builder_.add_PAGE(PAGE);
  builder_.add_ORIGIN_ID(ORIGIN_ID);
  builder_.add_PRODUCER_PEER_ID(PRODUCER_PEER_ID);
  builder_.add_BATCH_ID(BATCH_ID);
  builder_.add_SOURCE_NAME(SOURCE_NAME);
  builder_.add_PROVIDER_ID(PROVIDER_ID);
  builder_.add_SORT_FIELD(SORT_FIELD);
  builder_.add_FILTERS(FILTERS);
  builder_.add_SEARCH(SEARCH);
  builder_.add_SQL(SQL);
  builder_.add_FILE_IDENTIFIER(FILE_IDENTIFIER);
  builder_.add_SCHEMA_NAME(SCHEMA_NAME);
  builder_.add_RETRY_AFTER_MS(RETRY_AFTER_MS);
  builder_.add_MESSAGE(MESSAGE);
  builder_.add_ERROR_CODE(ERROR_CODE);
  builder_.add_STALE(STALE);
  builder_.add_TRUNCATED(TRUNCATED);
  builder_.add_PARTIAL(PARTIAL);
  builder_.add_SORT_DESC(SORT_DESC);
  builder_.add_STATUS(STATUS);
  builder_.add_KIND(KIND);
  return builder_.Finish();
}

inline ::flatbuffers::Offset<QRP> CreateQRPDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    qrpKind KIND = qrpKind_Request,
    qrpStatus STATUS = qrpStatus_Ok,
    const char *ERROR_CODE = nullptr,
    const char *MESSAGE = nullptr,
    uint32_t RETRY_AFTER_MS = 0,
    const char *SCHEMA_NAME = nullptr,
    const char *FILE_IDENTIFIER = nullptr,
    const char *SQL = nullptr,
    const char *SEARCH = nullptr,
    const std::vector<::flatbuffers::Offset<QRPFilter>> *FILTERS = nullptr,
    const char *SORT_FIELD = nullptr,
    bool SORT_DESC = false,
    const char *PROVIDER_ID = nullptr,
    const char *SOURCE_NAME = nullptr,
    const char *BATCH_ID = nullptr,
    const char *PRODUCER_PEER_ID = nullptr,
    const char *ORIGIN_ID = nullptr,
    int64_t FROM_EPOCH_MS = 0,
    int64_t TO_EPOCH_MS = 0,
    uint32_t PAGE = 0,
    uint32_t LIMIT = 0,
    const char *CURSOR = nullptr,
    const char *NEXT_CURSOR = nullptr,
    uint32_t RECORD_COUNT = 0,
    uint64_t TOTAL_COUNT = 0,
    uint64_t SCANNED = 0,
    uint64_t STORED = 0,
    bool PARTIAL = false,
    bool TRUNCATED = false,
    int64_t AS_OF_MS = 0,
    bool STALE = false,
    uint32_t ELAPSED_MS = 0,
    int64_t GENERATED_AT_MS = 0,
    const char *ETAG = nullptr,
    const char *CID = nullptr,
    const char *ARCHIVE_ID = nullptr,
    const std::vector<::flatbuffers::Offset<QRPColumn>> *COLUMNS = nullptr) {
  auto ERROR_CODE__ = ERROR_CODE ? _fbb.CreateString(ERROR_CODE) : 0;
  auto MESSAGE__ = MESSAGE ? _fbb.CreateString(MESSAGE) : 0;
  auto SCHEMA_NAME__ = SCHEMA_NAME ? _fbb.CreateString(SCHEMA_NAME) : 0;
  auto FILE_IDENTIFIER__ = FILE_IDENTIFIER ? _fbb.CreateString(FILE_IDENTIFIER) : 0;
  auto SQL__ = SQL ? _fbb.CreateString(SQL) : 0;
  auto SEARCH__ = SEARCH ? _fbb.CreateString(SEARCH) : 0;
  auto FILTERS__ = FILTERS ? _fbb.CreateVector<::flatbuffers::Offset<QRPFilter>>(*FILTERS) : 0;
  auto SORT_FIELD__ = SORT_FIELD ? _fbb.CreateString(SORT_FIELD) : 0;
  auto PROVIDER_ID__ = PROVIDER_ID ? _fbb.CreateString(PROVIDER_ID) : 0;
  auto SOURCE_NAME__ = SOURCE_NAME ? _fbb.CreateString(SOURCE_NAME) : 0;
  auto BATCH_ID__ = BATCH_ID ? _fbb.CreateString(BATCH_ID) : 0;
  auto PRODUCER_PEER_ID__ = PRODUCER_PEER_ID ? _fbb.CreateString(PRODUCER_PEER_ID) : 0;
  auto ORIGIN_ID__ = ORIGIN_ID ? _fbb.CreateString(ORIGIN_ID) : 0;
  auto CURSOR__ = CURSOR ? _fbb.CreateString(CURSOR) : 0;
  auto NEXT_CURSOR__ = NEXT_CURSOR ? _fbb.CreateString(NEXT_CURSOR) : 0;
  auto ETAG__ = ETAG ? _fbb.CreateString(ETAG) : 0;
  auto CID__ = CID ? _fbb.CreateString(CID) : 0;
  auto ARCHIVE_ID__ = ARCHIVE_ID ? _fbb.CreateString(ARCHIVE_ID) : 0;
  auto COLUMNS__ = COLUMNS ? _fbb.CreateVector<::flatbuffers::Offset<QRPColumn>>(*COLUMNS) : 0;
  return CreateQRP(
      _fbb,
      KIND,
      STATUS,
      ERROR_CODE__,
      MESSAGE__,
      RETRY_AFTER_MS,
      SCHEMA_NAME__,
      FILE_IDENTIFIER__,
      SQL__,
      SEARCH__,
      FILTERS__,
      SORT_FIELD__,
      SORT_DESC,
      PROVIDER_ID__,
      SOURCE_NAME__,
      BATCH_ID__,
      PRODUCER_PEER_ID__,
      ORIGIN_ID__,
      FROM_EPOCH_MS,
      TO_EPOCH_MS,
      PAGE,
      LIMIT,
      CURSOR__,
      NEXT_CURSOR__,
      RECORD_COUNT,
      TOTAL_COUNT,
      SCANNED,
      STORED,
      PARTIAL,
      TRUNCATED,
      AS_OF_MS,
      STALE,
      ELAPSED_MS,
      GENERATED_AT_MS,
      ETAG__,
      CID__,
      ARCHIVE_ID__,
      COLUMNS__);
}

inline const QRP *GetQRP(const void *buf) {
  return ::flatbuffers::GetRoot<QRP>(buf);
}

inline const QRP *GetSizePrefixedQRP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<QRP>(buf);
}

inline const char *QRPIdentifier() {
  return "$QRP";
}

inline bool QRPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, QRPIdentifier());
}

inline bool SizePrefixedQRPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, QRPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyQRPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<QRP>(QRPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedQRPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<QRP>(QRPIdentifier());
}

inline void FinishQRPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<QRP> root) {
  fbb.Finish(root, QRPIdentifier());
}

inline void FinishSizePrefixedQRPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<QRP> root) {
  fbb.FinishSizePrefixed(root, QRPIdentifier());
}

